  "team-members": {
    "React": "const TEAM = [\n  { name: \"Ada Lovelace\", role: \"Owner\", initials: \"AL\" },\n  { name: \"Grace Hopper\", role: \"Admin\", initials: \"GH\" },\n  { name: \"Alan Turing\", role: \"Member\", initials: \"AT\" },\n];\n\nexport function TeamMembersBlock() {\n  return (\n    <Card className=\"w-full max-w-sm\">\n      <CardHeader>\n        <CardTitle>Team</CardTitle>\n      </CardHeader>\n      <Separator />\n      <CardContent className=\"p-0\">\n        <List>\n          {TEAM.map((m) => (\n            <ListItem\n              key={m.name}\n              leading={\n                <Avatar>\n                  <AvatarFallback>{m.initials}</AvatarFallback>\n                </Avatar>\n              }\n              title={m.name}\n              description={m.role}\n              trailing={\n                <Button variant=\"Ghost\" size=\"sm\">\n                  Remove\n                </Button>\n              }\n            />\n          ))}\n        </List>\n      </CardContent>\n    </Card>\n  );\n}",
    "Compose": "data class TeamMember(val name: String, val role: String, val initials: String)\n\n@Composable\nfun TeamMembersBlock(\n    team: List<TeamMember> = listOf(\n        TeamMember(\"Ada Lovelace\", \"Owner\", \"AL\"),\n        TeamMember(\"Grace Hopper\", \"Admin\", \"GH\"),\n        TeamMember(\"Alan Turing\", \"Member\", \"AT\"),\n    ),\n    onRemove: (TeamMember) -> Unit = {},\n) {\n    KinetixCard(Modifier.width(360.dp)) {\n        KinetixCardHeader { KinetixCardTitle(\"Team\") }\n        KinetixSeparator()\n        KinetixList {\n            team.forEach { member ->\n                KinetixListItem(\n                    title = member.name,\n                    description = member.role,\n                    leading = { KinetixAvatar { KinetixAvatarFallback(member.initials) } },\n                    trailing = {\n                        KinetixButton(\n                            { onRemove(member) },\n                            variant = KinetixButtonVariant.Ghost,\n                            size = KinetixButtonSize.Sm,\n                        ) { Text(\"Remove\") }\n                    },\n                )\n            }\n        }\n    }\n}",
    "Flutter": "class TeamMember {\n  const TeamMember(this.name, this.role, this.initials);\n\n  final String name;\n  final String role;\n  final String initials;\n}\n\nclass TeamMembersBlock extends StatelessWidget {\n  const TeamMembersBlock({super.key, this.team = defaultTeam, this.onRemove});\n\n  static const List<TeamMember> defaultTeam = <TeamMember>[\n    TeamMember('Ada Lovelace', 'Owner', 'AL'),\n    TeamMember('Grace Hopper', 'Admin', 'GH'),\n    TeamMember('Alan Turing', 'Member', 'AT'),\n  ];\n\n  final List<TeamMember> team;\n  final void Function(TeamMember)? onRemove;\n\n  @override\n  Widget build(BuildContext context) {\n    return KinetixCard(\n      child: Column(\n        mainAxisSize: MainAxisSize.min,\n        children: <Widget>[\n          const KinetixCardHeader(children: <Widget>[KinetixCardTitle('Team')]),\n          const KinetixSeparator(),\n          KinetixList(\n            children: <Widget>[\n              for (final TeamMember member in team)\n                KinetixListItem(\n                  title: member.name,\n                  description: member.role,\n                  leading: KinetixAvatar(child: KinetixAvatarFallback(member.initials)),\n                  trailing: KinetixButton(\n                    onPressed: onRemove == null ? null : () => onRemove!(member),\n                    variant: KinetixButtonVariant.ghost,\n                    size: KinetixButtonSize.sm,\n                    child: const Text('Remove'),\n                  ),\n                ),\n            ],\n          ),\n        ],\n      ),\n    );\n  }\n}",
  },
  "comment-box": {
    "React": "export function CommentBoxBlock() {\n  return (\n    <Card className=\"w-full max-w-md\">\n      <CardContent className=\"flex items-start gap-3 pt-6\">\n        <Avatar>\n          <AvatarFallback>ZF</AvatarFallback>\n        </Avatar>\n        <div className=\"grid w-full gap-2\">\n          <Textarea placeholder=\"Add a comment…\" />\n          <Button className=\"ml-auto w-fit\">Comment</Button>\n        </div>\n      </CardContent>\n    </Card>\n  );\n}",
    "Compose": "@Composable\nfun CommentBoxBlock(onSubmit: (String) -> Unit = {}) {\n    var body by remember { mutableStateOf(\"\") }\n\n    KinetixCard(Modifier.width(420.dp)) {\n        KinetixCardContent {\n            Row(horizontalArrangement = Arrangement.spacedBy(12.dp)) {\n                KinetixAvatar { KinetixAvatarFallback(\"ZF\") }\n                Column(\n                    Modifier.weight(1f),\n                    verticalArrangement = Arrangement.spacedBy(8.dp),\n                    horizontalAlignment = Alignment.End,\n                ) {\n                    KinetixTextarea(body, { body = it }, placeholder = \"Add a comment…\")\n                    KinetixButton({ onSubmit(body) }) { Text(\"Comment\") }\n                }\n            }\n        }\n    }\n}",
    "Flutter": "class CommentBoxBlock extends StatefulWidget {\n  const CommentBoxBlock({super.key, this.onSubmit});\n\n  final void Function(String)? onSubmit;\n\n  @override\n  State<CommentBoxBlock> createState() => _CommentBoxBlockState();\n}\n\nclass _CommentBoxBlockState extends State<CommentBoxBlock> {\n  final TextEditingController _body = TextEditingController();\n\n  @override\n  void dispose() {\n    _body.dispose();\n    super.dispose();\n  }\n\n  @override\n  Widget build(BuildContext context) {\n    return KinetixCard(\n      child: KinetixCardContent(\n        child: Row(\n          crossAxisAlignment: CrossAxisAlignment.start,\n          children: <Widget>[\n            const KinetixAvatar(child: KinetixAvatarFallback('ZF')),\n            const SizedBox(width: 12),\n            Expanded(\n              child: Column(\n                crossAxisAlignment: CrossAxisAlignment.end,\n                children: <Widget>[\n                  KinetixTextarea(controller: _body, placeholder: 'Add a comment…'),\n                  const SizedBox(height: 8),\n                  KinetixButton(\n                    onPressed: widget.onSubmit == null ? null : () => widget.onSubmit!(_body.text),\n                    child: const Text('Comment'),\n                  ),\n                ],\n              ),\n            ),\n          ],\n        ),\n      ),\n    );\n  }\n}",
  },
